# -*- coding: utf-8 -*-
from entries1 import E
G='epreuves'
E('120',G,"Contre l'angoisse et la tristesse : « Je suis Ton serviteur »","Ô Allah, je suis Ton serviteur, fils de Ton serviteur, fils de Ta servante. Mon toupet est dans Ta main, Ton jugement s'accomplit sur moi et Ton décret à mon égard est juste. Je Te demande, par chacun des noms qui T'appartiennent, par lequel Tu T'es nommé, que Tu as révélé dans Ton Livre, que Tu as enseigné à l'une de Tes créatures ou que Tu as gardé dans la science de l'invisible auprès de Toi, de faire du Coran le printemps de mon cœur, la lumière de ma poitrine, ce qui dissipe ma tristesse et fait partir mon angoisse.")
E('121',G,"Contre le souci, la faiblesse et la dette","Ô Allah, je me réfugie auprès de Toi contre le souci et la tristesse, contre l'incapacité et la paresse, contre l'avarice et la lâcheté, contre le poids de la dette et la domination des hommes.")
E('122',G,"En cas de détresse : « Lâ ilâha illallâhul-'Azîmul-Halîm »","Il n'y a de divinité digne d'adoration qu'Allah, l'Immense, le Longanime. Il n'y a de divinité qu'Allah, Seigneur du Trône immense. Il n'y a de divinité qu'Allah, Seigneur des cieux, Seigneur de la terre et Seigneur du noble Trône.")
E('123',G,"En cas de détresse : « C'est Ta miséricorde que j'espère »","Ô Allah, c'est Ta miséricorde que j'espère : ne me confie pas à moi-même, ne serait-ce que le temps d'un clin d'œil, et améliore toute ma situation. Il n'y a de divinité digne d'adoration que Toi.")
E('124',G,"L'invocation de Yunus (Dhû n-Nûn)","Il n'y a de divinité digne d'adoration que Toi. Gloire à Toi ! J'ai certes été du nombre des injustes.",
  b="Aucun musulman n'invoque ainsi pour une chose sans qu'Allah ne l'exauce (At-Tirmidhi).")
E('125',G,"« Allah, Allah est mon Seigneur »","Allah, Allah est mon Seigneur, je ne Lui associe rien.")
E('128',G,"Face à une menace : « Hasbunallâh wa ni'mal-wakîl »","Allah nous suffit, et quel excellent garant !")
E('132',G,"Quand on craint des gens","Ô Allah, suffis-moi contre eux par ce que Tu veux.")
E('133',G,"En cas de doute dans la foi (1)","Je cherche refuge auprès d'Allah.",ar="أَعُوذُ بِاللَّهِ",tr="A'ūdhu billāh",note="Puis cesser de suivre la pensée qui fait douter.")
E('134',G,"En cas de doute dans la foi (2)","J'ai cru en Allah et en Ses messagers.",ar="آمَنْتُ بِاللَّهِ وَرُسُلِهِ",tr="Āmantu billāhi wa rusulih")
E('135',G,"En cas de doute dans la foi (3) : Al-Hadîd 57:3","C'est Lui le Premier et le Dernier, l'Apparent et le Caché, et Il est Omniscient.",ar="﴿هُوَ الْأَوَّلُ وَالْآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ ۖ وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ﴾")
E('136',G,"Pour le règlement d'une dette (1)","Ô Allah, suffis-moi par ce qui est licite au lieu de ce qui est illicite, et enrichis-moi par Ta grâce afin que je n'aie besoin de nul autre que Toi.")
E('137',G,"Pour le règlement d'une dette (2)","Ô Allah, je me réfugie auprès de Toi contre le souci et la tristesse, contre l'incapacité et la paresse, contre la lâcheté et l'avarice, contre le poids de la dette et la domination des hommes.")
E('138',G,"Contre les insufflations pendant la prière","Je cherche refuge auprès d'Allah contre le Diable banni.",c=3,note="Puis cracher légèrement (souffle sans salive) vers la gauche, trois fois.")
E('139',G,"Quand une affaire devient difficile","Ô Allah, rien n'est facile sauf ce que Tu rends facile, et Tu rends facile, si Tu le veux, ce qui est difficile.")
E('141',G,"Pour chasser le Diable","Je cherche refuge auprès d'Allah, l'Audient, l'Omniscient, contre le Diable banni.",
  ar="أَعُوذُ بِاللَّهِ السَّمِيعِ الْعَلِيمِ مِنَ الشَّيْطَانِ الرَّجِيمِ",tr="A'ūdhu billāhis-samī'il-'alīmi minash-shayṭānir-rajīm",
  note="Le Hisn al-Muslim mentionne aussi l'appel à la prière, le dhikr et la récitation du Coran (notamment la sourate Al-Baqara) pour éloigner le Diable.")
E('154',G,"Frappé par un malheur","Nous sommes à Allah et c'est vers Lui que nous retournerons. Ô Allah, récompense-moi dans mon malheur et donne-moi en échange quelque chose de meilleur.",
  b="Allah lui accorde en échange quelque chose de meilleur (Muslim).")
E('193',G,"Contre la colère","Je cherche refuge auprès d'Allah contre le Diable banni.")
E('203',G,"Par crainte du polythéisme (shirk)","Ô Allah, je me réfugie auprès de Toi contre le fait de T'associer quoi que ce soit en le sachant, et je Te demande pardon pour ce que je ne sais pas.")
E('205',G,"Contre la superstition (mauvais présages)","Ô Allah, il n'y a de présage que le Tien, il n'y a de bien que le Tien, et il n'y a de divinité digne d'adoration que Toi.")
E('247',G,"Contre la ruse des démons rebelles","Je me réfugie dans les paroles parfaites d'Allah, que ni le pieux ni le pervers ne peuvent dépasser, contre le mal de ce qu'Il a créé, façonné et répandu, contre le mal de ce qui descend du ciel et de ce qui y monte, contre le mal de ce qu'Il a répandu sur la terre et de ce qui en sort, contre le mal des épreuves de la nuit et du jour, et contre le mal de tout visiteur nocturne, sauf celui qui vient avec un bien, ô Tout Miséricordieux.")

G='repas'
E('178',G,"Avant de manger","Au nom d'Allah. (En cas d'oubli au début : au nom d'Allah, au début et à la fin.)",
  ar="بِسْمِ اللَّهِ — فَإِنْ نَسِيَ فِي أَوَّلِهِ: بِسْمِ اللَّهِ فِي أَوَّلِهِ وَآخِرِهِ",tr="Bismillāh — (en cas d'oubli :) Bismillāhi fī awwalihi wa ākhirih")
E('179',G,"Après avoir reçu de la nourriture ou du lait","Ô Allah, bénis-le pour nous et donne-nous à manger meilleur que lui. (Pour le lait : Ô Allah, bénis-le pour nous et donne-nous-en davantage.)",
  ar="اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَأَطْعِمْنَا خَيْراً مِنْهُ — (لِلَّبَنِ:) اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَزِدْنَا مِنْهُ",
  tr="Allāhumma bārik lanā fīhi wa aṭ'imnā khayran minh — (lait :) Allāhumma bārik lanā fīhi wa zidnā minh")
E('180',G,"Après le repas (1)","Louange à Allah qui m'a nourri de ceci et me l'a accordé sans force ni pouvoir de ma part.",b="Ses péchés passés lui sont pardonnés (At-Tirmidhi, Abu Dawud, Ibn Majah).")
E('181',G,"Après le repas (2)","Louange à Allah, une louange abondante, bonne et bénie, dont on ne saurait se passer, qu'on ne saurait délaisser et dont on ne peut se dispenser, ô notre Seigneur.")
E('182',G,"L'invité pour son hôte","Ô Allah, bénis-les dans ce que Tu leur as accordé, pardonne-leur et fais-leur miséricorde.")
E('183',G,"Pour celui qui nous a donné à manger ou à boire","Ô Allah, nourris celui qui m'a nourri et abreuve celui qui m'a abreuvé.")
E('176',G,"En rompant le jeûne","La soif est partie, les veines sont humectées et la récompense est acquise, si Allah le veut.")
E('184',G,"En rompant le jeûne chez quelqu'un","Que les jeûneurs rompent leur jeûne chez vous, que les pieux mangent votre nourriture et que les anges prient pour vous.")
E('186',G,"Au jeûneur que l'on insulte","Je jeûne, je jeûne.")
E('187',G,"En voyant les premiers fruits","Ô Allah, bénis-nous dans nos fruits, bénis-nous dans notre ville, bénis-nous dans notre sâ' et bénis-nous dans notre mudd (nos mesures).")

G='voyage'
E('206',G,"En montant sur une monture ou dans un véhicule","Au nom d'Allah. Louange à Allah. « Gloire à Celui qui a mis ceci à notre service alors que nous n'en étions pas capables ; et c'est vers notre Seigneur que nous retournerons. » Louange à Allah, louange à Allah, louange à Allah. Allah est le plus Grand, Allah est le plus Grand, Allah est le plus Grand. Gloire à Toi, ô Allah, j'ai été injuste envers moi-même, pardonne-moi, car nul ne pardonne les péchés que Toi.")
E('207',G,"L'invocation du voyage","Allah est le plus Grand (3 fois). « Gloire à Celui qui a mis ceci à notre service alors que nous n'en étions pas capables ; et c'est vers notre Seigneur que nous retournerons. » Ô Allah, nous Te demandons, dans ce voyage, la piété, la crainte et les œuvres que Tu agrées. Ô Allah, facilite-nous ce voyage et raccourcis-en pour nous la distance. Ô Allah, Tu es le Compagnon du voyage et le Gardien de la famille. Ô Allah, je me réfugie auprès de Toi contre la fatigue du voyage, contre un spectacle affligeant et contre un mauvais retour dans les biens et la famille. (Au retour, ajouter : « Nous revenons, repentants, adorant notre Seigneur et Le louant ».)")
E('208',G,"En entrant dans une ville ou un village","Ô Allah, Seigneur des sept cieux et de ce qu'ils ombragent, Seigneur des sept terres et de ce qu'elles portent, Seigneur des démons et de ceux qu'ils égarent, Seigneur des vents et de ce qu'ils dispersent, je Te demande le bien de ce village, le bien de ses habitants et le bien de ce qu'il contient, et je me réfugie auprès de Toi contre son mal, le mal de ses habitants et le mal de ce qu'il contient.")
E('209',G,"En entrant au marché","Il n'y a de divinité digne d'adoration qu'Allah, Seul, sans associé. À Lui la royauté, à Lui la louange ; Il donne la vie et la mort ; Il est Vivant et ne meurt pas ; dans Sa main est le bien, et Il est capable de toute chose.",
  b="Allah lui inscrit un million de bonnes actions, efface un million de mauvaises et l'élève d'un million de degrés (At-Tirmidhi ; hasan selon Al-Albani).")
E('210',G,"Quand la monture trébuche","Au nom d'Allah.")
E('211',G,"Le voyageur à ceux qui restent","Je vous confie à Allah, auprès de qui rien de ce qui Lui est confié ne se perd.")
E('212',G,"Celui qui reste au voyageur (1)","Je confie à Allah ta religion, ce dont tu as la charge et la fin de tes œuvres.")
E('213',G,"Celui qui reste au voyageur (2)","Qu'Allah te donne la piété pour provision, qu'Il pardonne ton péché et qu'Il te facilite le bien où que tu sois.")
E('216',G,"En faisant halte quelque part","Je me réfugie dans les paroles parfaites d'Allah contre le mal de ce qu'Il a créé.",b="Rien ne lui nuira jusqu'à ce qu'il quitte ce lieu (Muslim).")
E('217',G,"Au retour de voyage","(Allahu akbar 3 fois sur chaque hauteur, puis :) Il n'y a de divinité digne d'adoration qu'Allah, Seul, sans associé. À Lui la royauté, à Lui la louange, et Il est capable de toute chose. Nous revenons, repentants, adorant notre Seigneur et Le louant. Allah a tenu Sa promesse, secouru Son serviteur et vaincu seul les coalisés.")

G='quotidien'
E('188',G,"L'éternuement","Celui qui éternue dit : « Louange à Allah ». On lui répond : « Qu'Allah te fasse miséricorde ». Il répond : « Qu'Allah vous guide et améliore votre état ».",
  ar="الْحَمْدُ لِلَّهِ — يَرْحَمُكَ اللَّهُ — يَهْدِيكُمُ اللَّهُ وَيُصْلِحُ بَالَكُمْ",tr="Al-ḥamdu lillāh — Yarḥamukallāh — Yahdīkumullāhu wa yuṣliḥu bālakum")
E('190',G,"Au jeune marié","Qu'Allah te bénisse, qu'Il répande sur toi Sa bénédiction et qu'Il vous unisse dans le bien.")
E('192',G,"Avant le rapport conjugal","Au nom d'Allah. Ô Allah, écarte de nous le Diable et écarte le Diable de ce que Tu nous accordes.")
E('194',G,"En voyant quelqu'un éprouvé","Louange à Allah qui m'a préservé de ce dont Il t'a éprouvé et qui m'a nettement favorisé sur beaucoup de ceux qu'Il a créés.",note="À dire à voix basse, sans blesser la personne.")
E('196',G,"Expiation de l'assemblée (kaffârat al-majlis)","Gloire à Toi, ô Allah, et louange à Toi. Je témoigne qu'il n'y a de divinité digne d'adoration que Toi ; je Te demande pardon et je me repens à Toi.",
  b="Ce qui s'est dit de mal dans l'assemblée lui est pardonné (Abu Dawud, At-Tirmidhi).")
E('197',G,"À qui te dit « Qu'Allah te pardonne »","Et à toi aussi.")
E('198',G,"À qui te fait du bien","Qu'Allah te récompense par le bien.",b="Celui qui dit cela a pleinement loué (At-Tirmidhi).")
E('200',G,"À qui te dit « Je t'aime pour Allah »","Que t'aime Celui pour qui tu m'aimes.")
E('201',G,"À qui t'offre de son bien","Qu'Allah te bénisse dans ta famille et dans tes biens.")
E('202',G,"Au créancier en le remboursant","Qu'Allah te bénisse dans ta famille et dans tes biens. La récompense du prêt est la louange et le remboursement.")
E('204',G,"À qui te dit « Qu'Allah te bénisse »","Et qu'Allah te bénisse aussi.")
E('146',G,"Placer ses enfants sous la protection d'Allah","Je vous place sous la protection des paroles parfaites d'Allah contre tout démon, toute bête nuisible et tout œil envieux.",
  note="Le Prophète ﷺ le disait pour Al-Hasan et Al-Husayn.")
E('218',G,"Face à une bonne ou une mauvaise nouvelle","Louange à Allah par la grâce de qui s'accomplissent les bonnes choses. (Face à ce qui déplaît : Louange à Allah en toute circonstance.)")
E('240',G,"En cas d'étonnement (1)","Gloire à Allah !")
E('241',G,"En cas d'étonnement ou de joie (2)","Allah est le plus Grand !")
E('243',G,"En ressentant une douleur au corps","Poser la main sur l'endroit douloureux et dire « Au nom d'Allah » 3 fois, puis 7 fois : je me réfugie auprès d'Allah et de Sa puissance contre le mal de ce que je ressens et de ce que je crains.",c=7,
  ar="بِسْمِ اللَّهِ (ثَلاَثاً) — أَعُوذُ بِاللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ وَأُحَاذِرُ",tr="Bismillāh (×3) — A'ūdhu billāhi wa qudratihi min sharri mā ajidu wa uḥādhir")
E('245',G,"En cas de frayeur","Il n'y a de divinité digne d'adoration qu'Allah !")
E('227',G,"Rendre le salut à un non-musulman","Et sur vous.",ar="وَعَلَيْكُمْ",tr="Wa 'alaykum")

G='meteo'
E('166',G,"Quand le vent souffle (1)","Ô Allah, je Te demande son bien et je me réfugie auprès de Toi contre son mal.")
E('167',G,"Quand le vent souffle (2)","Ô Allah, je Te demande son bien, le bien de ce qu'il contient et le bien de ce avec quoi il a été envoyé ; et je me réfugie auprès de Toi contre son mal, le mal de ce qu'il contient et le mal de ce avec quoi il a été envoyé.")
E('168',G,"En entendant le tonnerre","Gloire à Celui dont le tonnerre célèbre la louange, ainsi que les anges, par crainte de Lui.")
E('169',G,"Demander la pluie (1)","Ô Allah, abreuve-nous d'une pluie secourable, salutaire, bénéfique et non nuisible, prompte et non tardive.")
E('170',G,"Demander la pluie (2)","Ô Allah, secours-nous (par la pluie). Ô Allah, secours-nous. Ô Allah, secours-nous.")
E('171',G,"Demander la pluie (3)","Ô Allah, abreuve Tes serviteurs et Tes bêtes, répands Ta miséricorde et redonne vie à Ta terre morte.")
E('172',G,"Quand il pleut","Ô Allah, (fais-en) une pluie bénéfique.")
E('173',G,"Après la pluie","Nous avons reçu la pluie par la grâce d'Allah et Sa miséricorde.")
E('174',G,"Demander l'arrêt de la pluie","Ô Allah, autour de nous et non sur nous. Ô Allah, sur les collines, les monts, le fond des vallées et là où poussent les arbres.")
E('175',G,"En voyant le croissant de lune","Allah est le plus Grand. Ô Allah, fais-le se lever sur nous dans la sécurité et la foi, la paix et l'Islam, et la réussite dans ce que Tu aimes et agrées. Notre Seigneur et ton Seigneur est Allah.")

G='malade'
E('147',G,"En rendant visite à un malade (1)","Ce n'est rien : (c'est) une purification, si Allah le veut.")
E('148',G,"En rendant visite à un malade (2)","Je demande à Allah l'Immense, Seigneur du Trône immense, de te guérir.",c=7,
  b="Si sa fin n'est pas arrivée, Allah le guérit (At-Tirmidhi, Abu Dawud).")
E('150',G,"Le malade qui sent venir la mort","Ô Allah, pardonne-moi, fais-moi miséricorde et réunis-moi avec le Compagnon suprême.")
E('152',G,"Paroles de la fin de vie","Il n'y a de divinité qu'Allah, et Allah est le plus Grand. Il n'y a de divinité qu'Allah, Seul. Il n'y a de divinité qu'Allah, Seul, sans associé. Il n'y a de divinité qu'Allah, à Lui la royauté et à Lui la louange. Il n'y a de divinité qu'Allah, et il n'y a de force ni de puissance qu'en Allah.",
  b="Celui dont la dernière parole est « Lâ ilâha illallâh » entre au Paradis (Abu Dawud).")
E('155',G,"En fermant les yeux du défunt","Ô Allah, pardonne à [nom], élève son rang parmi les bien-guidés, succède-lui auprès de ceux qu'il laisse, pardonne-nous ainsi qu'à lui, ô Seigneur des mondes, élargis sa tombe et illumine-la pour lui.")
E('156',G,"Prière funéraire (1)","Ô Allah, pardonne-lui, fais-lui miséricorde, préserve-le et efface ses fautes. Honore son accueil, élargis sa demeure, lave-le avec l'eau, la neige et la grêle, purifie-le de ses péchés comme on purifie le vêtement blanc de la saleté. Donne-lui une demeure meilleure que la sienne, une famille meilleure que la sienne et une épouse meilleure que la sienne ; fais-le entrer au Paradis et protège-le du châtiment de la tombe [et du châtiment du Feu].")
E('157',G,"Prière funéraire (2)","Ô Allah, pardonne à nos vivants et à nos morts, à nos présents et à nos absents, à nos petits et à nos grands, à nos hommes et à nos femmes. Ô Allah, celui d'entre nous que Tu fais vivre, fais-le vivre dans l'Islam, et celui que Tu fais mourir, fais-le mourir dans la foi. Ô Allah, ne nous prive pas de sa récompense et ne nous égare pas après lui.")
E('159',G,"Prière funéraire (3)","Ô Allah, Ton serviteur, fils de Ta servante, a besoin de Ta miséricorde et Tu n'as nul besoin de le châtier. S'il était bienfaisant, augmente ses bonnes actions ; et s'il était fautif, passe outre ses fautes.")
E('161',G,"Prière funéraire pour un enfant","Ô Allah, fais de lui pour nous un précurseur, un devancier et une source de récompense.")
E('162',G,"Présenter ses condoléances","À Allah appartient ce qu'Il a pris et à Lui ce qu'Il a donné ; toute chose a auprès de Lui un terme fixé. Patiente et espère la récompense. (On peut dire aussi : Qu'Allah augmente ta récompense, qu'Il te console au mieux et qu'Il pardonne à ton défunt.)",
  ar="إِنَّ لِلَّهِ مَا أَخَذَ، وَلَهُ مَا أَعْطَى، وَكُلُّ شَيْءٍ عِنْدَهُ بِأَجَلٍ مُسَمًّى، فَلْتَصْبِرْ وَلْتَحْتَسِبْ — أَعْظَمَ اللَّهُ أَجْرَكَ، وَأَحْسَنَ عَزَاءَكَ، وَغَفَرَ لِمَيِّتِكَ",
  tr="Inna lillāhi mā akhadha wa lahu mā a'ṭā, wa kullu shay'in 'indahu bi-ajalin musammā, faltaṣbir waltaḥtasib — A'ẓamallāhu ajrak, wa aḥsana 'azā'ak, wa ghafara li-mayyitik")
E('163',G,"En déposant le défunt dans la tombe","Au nom d'Allah, et selon la tradition du Messager d'Allah.")
E('164',G,"Après l'enterrement","Ô Allah, pardonne-lui. Ô Allah, affermis-le.")
E('165',G,"En visitant les tombes","Que la paix soit sur vous, habitants de ces demeures, croyants et musulmans ; et nous vous rejoindrons, si Allah le veut. [Qu'Allah fasse miséricorde à ceux d'entre nous qui sont partis les premiers et à ceux qui partiront plus tard.] Je demande à Allah le salut pour nous et pour vous.")

G='dhikr'
E('254',G,"Subhanallahi wa bihamdihi (100 fois par jour)","Gloire et louange à Allah.",c=100,v=[('bukhari',6405),('muslim',2691)],
  ar="سُبْحَانَ اللَّهِ وَبِحَمْدِهِ",tr="Subḥānallāhi wa biḥamdih",b="Ses péchés sont effacés, seraient-ils comme l'écume de la mer.")
E('256',G,"Deux paroles légères sur la langue","Gloire et louange à Allah ; gloire à Allah l'Immense.",ar="سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ",tr="Subḥānallāhi wa biḥamdih, subḥānallāhil-'aẓīm",
  b="Légères sur la langue, lourdes dans la balance, aimées du Tout Miséricordieux.")
E('261',G,"Les quatre paroles les plus aimées d'Allah","Gloire à Allah, louange à Allah, il n'y a de divinité qu'Allah, et Allah est le plus Grand.",
  ar="سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ",tr="Subḥānallāh, wal-ḥamdu lillāh, wa lā ilāha illallāh, wallāhu akbar",
  note="Peu importe par laquelle on commence (Muslim).")
E('258',G,"Subhanallah 100 fois : mille bonnes actions","Gloire à Allah.",c=100,ar="سُبْحَانَ اللَّهِ",tr="Subḥānallāh",b="Mille bonnes actions sont écrites, ou mille péchés effacés.")
E('260',G,"Un trésor du Paradis : « Lâ hawla wa lâ quwwata illâ billâh »","Il n'y a de force ni de puissance qu'en Allah.",ar="لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ",tr="Lā ḥawla wa lā quwwata illā billāh",b="L'un des trésors du Paradis.")
E('262',G,"Parole enseignée au Bédouin","Il n'y a de divinité digne d'adoration qu'Allah, Seul, sans associé. Allah est le plus Grand, très grandement ; louange abondante à Allah ; gloire à Allah, Seigneur des mondes ; il n'y a de force ni de puissance qu'en Allah, le Tout-Puissant, le Sage. (Puis, pour soi :) Ô Allah, pardonne-moi, fais-moi miséricorde, guide-moi et accorde-moi ma subsistance.",
  ar="لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، اللَّهُ أَكْبَرُ كَبِيراً، وَالْحَمْدُ لِلَّهِ كَثِيراً، سُبْحَانَ اللَّهِ رَبِّ العَالَمِينَ، لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ الْعَزِيزِ الْحَكِيمِ — اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَارْزُقْنِي",
  tr="Lā ilāha illallāhu waḥdahu lā sharīka lah, Allāhu akbaru kabīrā, wal-ḥamdu lillāhi kathīrā, subḥānallāhi rabbil-'ālamīn, lā ḥawla wa lā quwwata illā billāhil-'azīzil-ḥakīm — Allāhummaghfir lī, warḥamnī, wahdinī, warzuqnī")
E('263',G,"L'invocation enseignée aux nouveaux musulmans","Ô Allah, pardonne-moi, fais-moi miséricorde, guide-moi, accorde-moi le bien-être et accorde-moi ma subsistance.",
  ar="اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَعَافِنِي، وَارْزُقْنِي",tr="Allāhummaghfir lī, warḥamnī, wahdinī, wa 'āfinī, warzuqnī",note="Ces paroles réunissent le bien de ce monde et de l'au-delà (Muslim).")
E('265',G,"Les bonnes œuvres durables (al-bâqiyât as-sâlihât)","Gloire à Allah, louange à Allah, il n'y a de divinité qu'Allah, Allah est le plus Grand, et il n'y a de force ni de puissance qu'en Allah.",
  ar="سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ",tr="Subḥānallāh, wal-ḥamdu lillāh, wa lā ilāha illallāh, wallāhu akbar, wa lā ḥawla wa lā quwwata illā billāh")
E('250',G,"Demande de pardon à Allah l'Immense, le Vivant","Je demande pardon à Allah l'Immense, en dehors de qui il n'y a de divinité digne d'adoration, le Vivant, Celui qui subsiste par Lui-même, et je me repens à Lui.",
  ar="أَسْتَغْفِرُ اللَّهَ الْعَظيمَ الَّذِي لاَ إِلَهَ إِلاَّ هُوَ الْحَيُّ القَيّوُمُ وَأَتُوبُ إِلَيهِ",tr="Astaghfirullāhal-'aẓīm alladhī lā ilāha illā huwal-ḥayyul-qayyūmu wa atūbu ilayh",
  b="Allah lui pardonne, même s'il avait fui le combat (Abu Dawud, At-Tirmidhi ; authentifié par Al-Albani).")
E('249',G,"Se repentir 100 fois par jour","Je demande pardon à Allah et je me repens à Lui.",c=100,v=[('muslim',2702)],
  ar="أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ",tr="Astaghfirullāha wa atūbu ilayh",note="« Ô gens, repentez-vous à Allah, car je me repens à Lui cent fois par jour. »")
